css:
/*Neo Brutalism data card*/
.card-sm {
  background-color: #fff;
  width: 250px;
  border-radius: 5px;
  box-shadow: 5px 5px #323232;
  border: 3px solid #323232;
  box-sizing: border-box;
}
.block-header {
  width: 100%;
  padding: 0.5rem;
  background-color: #f4dbda;
}
.block-title {
  display: flex;
  align-items: center;
}

.block-title span {
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
}

.block-title span svg {
  width: 1.5rem;
  height: 1.5rem;
}

.block-title-text {
  margin-left: 0.5rem;
  color: #374151;
  font-size: 18px;
}

.css-dom {
  width: 100%;
  height: 220px;
  border-radius: 4px;
  box-sizing: border-box;
  background-repeat: no-repeat;
  background-image: linear-gradient(lightgray, lightgray),
    linear-gradient(lightgray, lightgray), linear-gradient(lightgray, lightgray),
    linear-gradient(lightgray, lightgray), linear-gradient(lightgray, lightgray),
    linear-gradient(lightgray, lightgray), linear-gradient(lightgray, lightgray),
    linear-gradient(lightgray, lightgray), linear-gradient(#f4dbda, #f4dbda);

  background-size:
    96px 96px,
    110px 20px,
    110px 20px,
    110px 20px,
    110px 20px,
    215px 20px,
    75px 20px,
    75px 20px,
    250px 50px;

  background-position:
    10px 10px,
    115px 10px,
    115px 35px,
    115px 60px,
    115px 85px,
    10px 120px,
    30px 160px,
    125px 160px,
    1px 185px;

  border: 1px solid black;
}
